{
  "ir_version": "1.0",
  "process": {
    "id": "treatment-linked-bmp-scheduling",
    "name": "Treatment-Linked BMP Scheduling",
    "description": "Evaluate the Monitoring Plan using the selected treatment action and kidney disease status. Branch conditions mirror Decision Table 2 without assuming undocumented fields of its composite output. The human review tasks require an authorized reviewer to order and arrange the BMP for the applicable interval after medication initiation; review alone does not complete these tasks. The clinicians group is an authorization binding, not a source-specified ordering or scheduling actor. Lifestyle-only treatment creates no additional routine BMP under Table 2. Baseline testing and standard preventive care remain unaffected.",
    "isExecutable": true,
    "kind": "template",
    "properties": [],
    "flowElements": [
      {
        "id": "start",
        "name": "Treatment decision available",
        "acp": {
          "provenance": {
            "kind": "structural",
            "derivation_rule": "start-event",
            "supports": [
              "obtain_monitoring_plan"
            ]
          },
          "structural_constant": false
        },
        "type": "startEvent"
      },
      {
        "id": "obtain_monitoring_plan",
        "name": "Evaluate laboratory monitoring",
        "acp": {
          "provenance": {
            "kind": "source",
            "source_text": "The following table defines the recommended monitoring actions based on the treatment decision and comorbidity status:",
            "source_location": {
              "page_start": 3,
              "page_end": 3
            }
          },
          "structural_constant": false
        },
        "type": "businessRuleTask",
        "dmnModel": "monitoring-plan",
        "inputs": {
          "Treatment Action": {
            "param": "treatment_action"
          },
          "Has Kidney Disease": {
            "param": "has_kidney_disease"
          }
        },
        "outputs": {}
      },
      {
        "id": "select_lab_branch",
        "name": "Which laboratory plan applies?",
        "acp": {
          "provenance": {
            "kind": "structural",
            "derivation_rule": "exclusive-split",
            "supports": [
              "obtain_monitoring_plan",
              "f_two_week_bmp",
              "f_four_week_bmp",
              "f_no_additional_bmp"
            ]
          },
          "structural_constant": false
        },
        "type": "exclusiveGateway",
        "gatewayDirection": "Diverging",
        "default": "f_no_additional_bmp"
      },
      {
        "id": "review_two_week_bmp",
        "name": "Review, order and arrange BMP for two weeks after initiation",
        "acp": {
          "provenance": {
            "kind": "source",
            "source_text": "| Start medication            | Yes                  | Basic Metabolic Panel | 2                    |",
            "source_location": {
              "page_start": 3,
              "page_end": 3
            }
          },
          "structural_constant": false
        },
        "type": "userTask",
        "groupId": "clinicians",
        "outputs": {}
      },
      {
        "id": "review_four_week_bmp",
        "name": "Review, order and arrange BMP for four weeks after initiation",
        "acp": {
          "provenance": {
            "kind": "source",
            "source_text": "| Start medication            | No                   | Basic Metabolic Panel | 4                    |",
            "source_location": {
              "page_start": 3,
              "page_end": 3
            }
          },
          "structural_constant": false
        },
        "type": "userTask",
        "groupId": "clinicians",
        "outputs": {}
      },
      {
        "id": "end_two_week_arranged",
        "name": "Two-week BMP ordered and arranged",
        "acp": {
          "provenance": {
            "kind": "structural",
            "derivation_rule": "end-event",
            "supports": [
              "review_two_week_bmp"
            ]
          },
          "outcome": "two_week_bmp_arranged",
          "structural_constant": false
        },
        "type": "endEvent"
      },
      {
        "id": "end_four_week_arranged",
        "name": "Four-week BMP ordered and arranged",
        "acp": {
          "provenance": {
            "kind": "structural",
            "derivation_rule": "end-event",
            "supports": [
              "review_four_week_bmp"
            ]
          },
          "outcome": "four_week_bmp_arranged",
          "structural_constant": false
        },
        "type": "endEvent"
      },
      {
        "id": "end_no_additional_bmp",
        "name": "No additional routine BMP created",
        "acp": {
          "provenance": {
            "kind": "structural",
            "derivation_rule": "end-event",
            "supports": [
              "f_no_additional_bmp"
            ]
          },
          "outcome": "no_additional_bmp",
          "structural_constant": false
        },
        "type": "endEvent"
      },
      {
        "id": "period_elapsed",
        "name": "Maximum process duration elapsed",
        "acp": {
          "provenance": {
            "kind": "structural",
            "derivation_rule": "plan-bound",
            "supports": [
              "obtain_monitoring_plan",
              "review_two_week_bmp",
              "review_four_week_bmp"
            ]
          },
          "structural_constant": false
        },
        "type": "boundaryEvent",
        "attachedToRef": "main",
        "cancelActivity": true,
        "timerEventDefinition": {
          "timeDuration": {
            "param": "max_duration"
          }
        }
      },
      {
        "id": "end_timeout",
        "name": "Process duration elapsed",
        "acp": {
          "provenance": {
            "kind": "structural",
            "derivation_rule": "end-event",
            "supports": [
              "period_elapsed"
            ]
          },
          "outcome": "timed_out",
          "structural_constant": false
        },
        "type": "endEvent"
      },
      {
        "id": "f_start_plan",
        "name": "",
        "acp": {
          "provenance": {
            "kind": "structural",
            "derivation_rule": "sequence",
            "supports": [
              "start",
              "obtain_monitoring_plan"
            ]
          },
          "structural_constant": false
        },
        "type": "sequenceFlow",
        "sourceRef": "start",
        "targetRef": "obtain_monitoring_plan"
      },
      {
        "id": "f_plan_selection",
        "name": "",
        "acp": {
          "provenance": {
            "kind": "structural",
            "derivation_rule": "sequence",
            "supports": [
              "obtain_monitoring_plan",
              "select_lab_branch"
            ]
          },
          "structural_constant": false
        },
        "type": "sequenceFlow",
        "sourceRef": "obtain_monitoring_plan",
        "targetRef": "select_lab_branch"
      },
      {
        "id": "f_two_week_bmp",
        "name": "Medication with kidney disease",
        "acp": {
          "provenance": {
            "kind": "source",
            "source_text": "| Start medication            | Yes                  | Basic Metabolic Panel | 2                    |",
            "source_location": {
              "page_start": 3,
              "page_end": 3
            }
          },
          "structural_constant": false
        },
        "type": "sequenceFlow",
        "sourceRef": "select_lab_branch",
        "targetRef": "review_two_week_bmp",
        "conditionExpression": "defined(treatment_action) and treatment_action == \"Start medication\" and defined(has_kidney_disease) and has_kidney_disease == true"
      },
      {
        "id": "f_four_week_bmp",
        "name": "Medication without kidney disease",
        "acp": {
          "provenance": {
            "kind": "source",
            "source_text": "| Start medication            | No                   | Basic Metabolic Panel | 4                    |",
            "source_location": {
              "page_start": 3,
              "page_end": 3
            }
          },
          "structural_constant": false
        },
        "type": "sequenceFlow",
        "sourceRef": "select_lab_branch",
        "targetRef": "review_four_week_bmp",
        "conditionExpression": "defined(treatment_action) and treatment_action == \"Start medication\" and defined(has_kidney_disease) and has_kidney_disease == false"
      },
      {
        "id": "f_no_additional_bmp",
        "name": "Lifestyle-only treatment",
        "acp": {
          "provenance": {
            "kind": "source",
            "source_text": "Patients on lifestyle modification alone do not require routine laboratory monitoring beyond standard preventive care.",
            "source_location": {
              "page_start": 3,
              "page_end": 3
            }
          },
          "structural_constant": false
        },
        "type": "sequenceFlow",
        "sourceRef": "select_lab_branch",
        "targetRef": "end_no_additional_bmp"
      },
      {
        "id": "f_two_week_end",
        "name": "",
        "acp": {
          "provenance": {
            "kind": "structural",
            "derivation_rule": "sequence",
            "supports": [
              "review_two_week_bmp",
              "end_two_week_arranged"
            ]
          },
          "structural_constant": false
        },
        "type": "sequenceFlow",
        "sourceRef": "review_two_week_bmp",
        "targetRef": "end_two_week_arranged"
      },
      {
        "id": "f_four_week_end",
        "name": "",
        "acp": {
          "provenance": {
            "kind": "structural",
            "derivation_rule": "sequence",
            "supports": [
              "review_four_week_bmp",
              "end_four_week_arranged"
            ]
          },
          "structural_constant": false
        },
        "type": "sequenceFlow",
        "sourceRef": "review_four_week_bmp",
        "targetRef": "end_four_week_arranged"
      },
      {
        "id": "f_timeout",
        "name": "",
        "acp": {
          "provenance": {
            "kind": "structural",
            "derivation_rule": "sequence",
            "supports": [
              "period_elapsed",
              "end_timeout"
            ]
          },
          "structural_constant": false
        },
        "type": "sequenceFlow",
        "sourceRef": "period_elapsed",
        "targetRef": "end_timeout"
      }
    ],
    "acp": {
      "triggers": [
        {
          "kind": "recommendation",
          "recommendation_id": "2dde00bf-a9c8-458e-b64c-11f45d8719af"
        },
        {
          "kind": "recommendation",
          "recommendation_id": "96ea40c4-d53a-4a8c-9818-6189f25cf5e5"
        },
        {
          "kind": "recommendation",
          "recommendation_id": "da2adb48-858f-4778-b540-5ab5f70932ad"
        }
      ],
      "parameters": [
        {
          "name": "treatment_action",
          "type": "string",
          "constraints": {
            "enum": [
              "Start medication",
              "Lifestyle modification only"
            ],
            "source": {
              "kind": "cpg",
              "source_text": "| Start medication            | Yes                  | Basic Metabolic Panel | 2                    |\n| Start medication            | No                   | Basic Metabolic Panel | 4                    |\n| Lifestyle modification only | Yes                  | -                     | -                    |\n| Lifestyle modification only | No                   | -                     | -                    |",
              "source_location": {
                "page_start": 3,
                "page_end": 3
              }
            }
          },
          "required": true,
          "description": "Selected treatment action supplied to the monitoring decision.",
          "source": {
            "kind": "cpg",
            "source_text": "The following table defines the recommended monitoring actions based on the treatment decision and comorbidity status:",
            "source_location": {
              "page_start": 3,
              "page_end": 3
            }
          },
          "reserved": false
        },
        {
          "name": "has_kidney_disease",
          "type": "boolean",
          "required": true,
          "description": "Kidney disease status supplied to the monitoring decision.",
          "source": {
            "kind": "cpg",
            "source_text": "Patients initiating medication therapy require laboratory monitoring to assess for potential adverse effects, particularly in patients with pre-existing kidney disease.",
            "source_location": {
              "page_start": 3,
              "page_end": 3
            }
          },
          "reserved": false
        },
        {
          "name": "max_duration",
          "type": "duration",
          "required": true,
          "description": "Maximum duration of this automation, distinct from laboratory timing after medication initiation.",
          "reserved": true
        }
      ],
      "invariants": [],
